import{c as t,Q as e,j as o,m as l}from"./chunks/framework.CHJbb1iY.js";const s="/my-knowledge/assets/%E9%94%81-1.BdMn3R6w.png",r="/my-knowledge/assets/%E9%94%81-2.0CNxhQB4.png",n="/my-knowledge/assets/%E9%94%81-3.f9DgSv2U.png",i="/my-knowledge/assets/%E9%94%81-4.D8UFeSj-.png",d="/my-knowledge/assets/%E9%94%81-5.D6fZg31l.png",h="/my-knowledge/assets/%E9%94%81-6.BrYr9wr0.png",c="/my-knowledge/assets/%E9%94%81-7.DV2EPhDq.png",p="/my-knowledge/assets/%E9%94%81-8.g7a6x9GB.png",u="/my-knowledge/assets/%E9%94%81-9.D8dPc5Bn.png",q="/my-knowledge/assets/%E9%94%81-10.D6RQrOu6.png",b="/my-knowledge/assets/%E9%94%81-11.DDrMQ9JW.png",k="/my-knowledge/assets/%E9%94%81-12.CqZsA-Pe.png",g="/my-knowledge/assets/%E9%94%81-13.hjqddgE2.png",m="/my-knowledge/assets/%E9%94%81-14.BgTyB5Z8.png",y="/my-knowledge/assets/%E9%94%81-15.Cqa_eqZ2.png",_="/my-knowledge/assets/%E9%94%81-16.CICPUmnL.png",x="/my-knowledge/assets/%E9%94%81-17.BggrVvSK.png",f="/my-knowledge/assets/%E9%94%81-18.DlM5g4go.png",C=JSON.parse('{"title":"","description":"","frontmatter":{"outline":[2,3],"aside":"right"},"headers":[],"relativePath":"docs/后端/MySQL/MySQL/进阶篇/7. 锁.md","filePath":"docs/后端/MySQL/MySQL/进阶篇/7. 锁.md"}'),D={name:"docs/后端/MySQL/MySQL/进阶篇/7. 锁.md"};function P(B,a,E,w,A,v){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 style="text-align:center;">锁</h1><hr><h2 id="基本介绍" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h2><blockquote><h4 id="锁是计算机协调多个进程或线程并发访问某一资源的机制" tabindex="-1">锁是计算机协调<span style="color:red;">多个进程或线程并发访问</span>某一资源的机制 <a class="header-anchor" href="#锁是计算机协调多个进程或线程并发访问某一资源的机制" aria-label="Permalink to &quot;锁是计算机协调&lt;span style=&quot;color:red&quot;&gt;多个进程或线程并发访问&lt;/span&gt;某一资源的机制&quot;">​</a></h4><h4 id="在数据库中-除传统的计算资源-cpu、ram、i-o-的争用以外-数据也是一种供许多用户共享的资源-如何保证数据并发访问的一致性、有效性是所有数据库必须解决的一个问题-锁冲突也是影响数据库并发访问性能的一个重要因素。从这个角度来说-锁对数据库而言显得尤其重要-也更加复杂" tabindex="-1">在数据库中，除传统的计算资源（CPU、RAM、I/O）的争用以外，数据也是一种供许多用户共享的资源，如何保证数据<span style="color:red;">并发访问的一致性</span>、有效性是所有数据库必须解决的一个问题，锁冲突也是影响数据库并发访问性能的一个重要因素。从这个角度来说，锁对数据库而言显得尤其重要，也更加复杂 <a class="header-anchor" href="#在数据库中-除传统的计算资源-cpu、ram、i-o-的争用以外-数据也是一种供许多用户共享的资源-如何保证数据并发访问的一致性、有效性是所有数据库必须解决的一个问题-锁冲突也是影响数据库并发访问性能的一个重要因素。从这个角度来说-锁对数据库而言显得尤其重要-也更加复杂" aria-label="Permalink to &quot;在数据库中，除传统的计算资源（CPU、RAM、I/O）的争用以外，数据也是一种供许多用户共享的资源，如何保证数据&lt;span style=&quot;color:red&quot;&gt;并发访问的一致性&lt;/span&gt;、有效性是所有数据库必须解决的一个问题，锁冲突也是影响数据库并发访问性能的一个重要因素。从这个角度来说，锁对数据库而言显得尤其重要，也更加复杂&quot;">​</a></h4></blockquote><h4 id="mysql-中的锁-按照锁的力度分-分为以下三类" tabindex="-1">MySQL 中的锁，按照锁的力度分，分为以下三类 <a class="header-anchor" href="#mysql-中的锁-按照锁的力度分-分为以下三类" aria-label="Permalink to &quot;MySQL 中的锁，按照锁的力度分，分为以下三类&quot;">​</a></h4><blockquote><h4 id="全局锁-锁定数据库中的所有表" tabindex="-1">全局锁：锁定数据库中的所有表 <a class="header-anchor" href="#全局锁-锁定数据库中的所有表" aria-label="Permalink to &quot;全局锁：锁定数据库中的所有表&quot;">​</a></h4><h4 id="表级锁-每次操作锁住整张表" tabindex="-1">表级锁：每次操作锁住整张表 <a class="header-anchor" href="#表级锁-每次操作锁住整张表" aria-label="Permalink to &quot;表级锁：每次操作锁住整张表&quot;">​</a></h4><h4 id="行级锁-每次操作锁住对应的行数据" tabindex="-1">行级锁：每次操作锁住对应的行数据 <a class="header-anchor" href="#行级锁-每次操作锁住对应的行数据" aria-label="Permalink to &quot;行级锁：每次操作锁住对应的行数据&quot;">​</a></h4></blockquote><h2 id="全局锁" tabindex="-1">全局锁 <a class="header-anchor" href="#全局锁" aria-label="Permalink to &quot;全局锁&quot;">​</a></h2><h3 id="基本介绍-1" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍-1" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h3><blockquote><h4 id="全局锁就是对整个数据库实例加锁-加锁后整个实例就处于只读状态-后续的-dml-的写语句-ddl-语句-已经更新操作的事务提交语句都将被阻塞" tabindex="-1">全局锁就是<span style="color:red;">对整个数据库实例加锁</span>，<span style="color:red;">加锁后</span>整个实例就处于<span style="color:red;">只读状态</span>，后续的 DML 的写语句，DDL 语句，已经更新操作的事务提交语句都将被阻塞 <a class="header-anchor" href="#全局锁就是对整个数据库实例加锁-加锁后整个实例就处于只读状态-后续的-dml-的写语句-ddl-语句-已经更新操作的事务提交语句都将被阻塞" aria-label="Permalink to &quot;全局锁就是&lt;span style=&quot;color:red&quot;&gt;对整个数据库实例加锁&lt;/span&gt;，&lt;span style=&quot;color:red&quot;&gt;加锁后&lt;/span&gt;整个实例就处于&lt;span style=&quot;color:red&quot;&gt;只读状态&lt;/span&gt;，后续的 DML 的写语句，DDL 语句，已经更新操作的事务提交语句都将被阻塞&quot;">​</a></h4></blockquote><h3 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h3><blockquote><h4 id="其典型的使用场景是做全库的逻辑备份-对所有的表进行锁定-从而获取一致性视图-保证数据的完整性" tabindex="-1">其典型的使用场景是做<span style="color:red;">全库的逻辑备份</span>，对所有的表进行锁定，从而获取一致性视图，保证数据的完整性 <a class="header-anchor" href="#其典型的使用场景是做全库的逻辑备份-对所有的表进行锁定-从而获取一致性视图-保证数据的完整性" aria-label="Permalink to &quot;其典型的使用场景是做&lt;span style=&quot;color:red&quot;&gt;全库的逻辑备份&lt;/span&gt;，对所有的表进行锁定，从而获取一致性视图，保证数据的完整性&quot;">​</a></h4></blockquote><h4 id="_1-不加锁存在的问题" tabindex="-1">（1）不加锁存在的问题 <a class="header-anchor" href="#_1-不加锁存在的问题" aria-label="Permalink to &quot;（1）不加锁存在的问题&quot;">​</a></h4><h4 id="假设在数据库中存在这样三张表-tb-stock-库存表-tb-order-订单表-tb-orderlog-订单日志表" tabindex="-1">假设在数据库中存在这样三张表: tb_stock 库存表，tb_order 订单表，tb_orderlog 订单日志表 <a class="header-anchor" href="#假设在数据库中存在这样三张表-tb-stock-库存表-tb-order-订单表-tb-orderlog-订单日志表" aria-label="Permalink to &quot;假设在数据库中存在这样三张表: tb_stock 库存表，tb_order 订单表，tb_orderlog 订单日志表&quot;">​</a></h4><br><img src="'+s+'" style="width:800px;margin:0 auto;"><blockquote><h4 id="_1-在进行数据备份时-先备份了-tb-stock-库存表" tabindex="-1">（1）在进行数据备份时，先备份了 tb_stock 库存表 <a class="header-anchor" href="#_1-在进行数据备份时-先备份了-tb-stock-库存表" aria-label="Permalink to &quot;（1）在进行数据备份时，先备份了 tb_stock 库存表&quot;">​</a></h4><h4 id="_2-然后接下来-在业务系统中-执行了下单操作-扣减库存-生成订单-更新-tb-stock-表-插入-tb-order-表" tabindex="-1">（2）然后接下来，在业务系统中，<span style="color:red;">执行了下单操作，扣减库存</span>，生成订单（更新 tb_stock 表，插入 tb_order 表） <a class="header-anchor" href="#_2-然后接下来-在业务系统中-执行了下单操作-扣减库存-生成订单-更新-tb-stock-表-插入-tb-order-表" aria-label="Permalink to &quot;（2）然后接下来，在业务系统中，&lt;span style=&quot;color:red&quot;&gt;执行了下单操作，扣减库存&lt;/span&gt;，生成订单（更新 tb_stock 表，插入 tb_order 表）&quot;">​</a></h4><h4 id="_3-然后再执行备份-tb-order-表的逻辑" tabindex="-1">（3）然后再执行备份 tb_order 表的逻辑 <a class="header-anchor" href="#_3-然后再执行备份-tb-order-表的逻辑" aria-label="Permalink to &quot;（3）然后再执行备份 tb_order 表的逻辑&quot;">​</a></h4><h4 id="_4-业务中执行插入订单日志操作" tabindex="-1">（4）业务中执行插入订单日志操作 <a class="header-anchor" href="#_4-业务中执行插入订单日志操作" aria-label="Permalink to &quot;（4）业务中执行插入订单日志操作&quot;">​</a></h4><h4 id="_5-最后-又备份了-tb-orderlog-表" tabindex="-1">（5）最后，又备份了 tb_orderlog 表 <a class="header-anchor" href="#_5-最后-又备份了-tb-orderlog-表" aria-label="Permalink to &quot;（5）最后，又备份了 tb_orderlog 表&quot;">​</a></h4></blockquote><div class="tip custom-block"><p class="custom-block-title"><span style="font-size:18px;font-weight:bold;">⚠️ 问题分析</span></p><h4 id="此时备份出来的数据-是存在问题的-因为备份出来的数据-tb-stock-表与-tb-order-表的数据不一致-有最新操作的订单信息-但是库存数没减" tabindex="-1">此时备份出来的数据，是存在问题的，因为备份出来的数据，tb_stock 表与 tb_order 表的数据不一致（有最新操作的订单信息，但是库存数没减） <a class="header-anchor" href="#此时备份出来的数据-是存在问题的-因为备份出来的数据-tb-stock-表与-tb-order-表的数据不一致-有最新操作的订单信息-但是库存数没减" aria-label="Permalink to &quot;此时备份出来的数据，是存在问题的，因为备份出来的数据，tb_stock 表与 tb_order 表的数据不一致（有最新操作的订单信息，但是库存数没减）&quot;">​</a></h4></div><h4 id="_2-加锁后" tabindex="-1">（2）加锁后 <a class="header-anchor" href="#_2-加锁后" aria-label="Permalink to &quot;（2）加锁后&quot;">​</a></h4><br><img src="'+r+'" style="width:800px;margin:0 auto;"><blockquote><h4 id="对数据库进行进行逻辑备份之前-先对整个数据库加上全局锁" tabindex="-1">对数据库进行进行逻辑备份之前，先对整个数据库加上全局锁 <a class="header-anchor" href="#对数据库进行进行逻辑备份之前-先对整个数据库加上全局锁" aria-label="Permalink to &quot;对数据库进行进行逻辑备份之前，先对整个数据库加上全局锁&quot;">​</a></h4><h4 id="一旦加了全局锁之后-其他的-ddl、dml-全部都处于阻塞状态-但是可以执行-dql-语句-也就是处于只读状态-而数据备份就是查询操作" tabindex="-1">一旦加了全局锁之后，其他的 DDL、DML 全部都处于阻塞状态，但是可以执行 DQL 语句，也就是处于只读状态，而数据备份就是查询操作 <a class="header-anchor" href="#一旦加了全局锁之后-其他的-ddl、dml-全部都处于阻塞状态-但是可以执行-dql-语句-也就是处于只读状态-而数据备份就是查询操作" aria-label="Permalink to &quot;一旦加了全局锁之后，其他的 DDL、DML 全部都处于阻塞状态，但是可以执行 DQL 语句，也就是处于只读状态，而数据备份就是查询操作&quot;">​</a></h4><h4 id="那么数据在进行逻辑备份的过程中-数据库中的数据就是不会发生变化的-这样就保证了数据的一致性和完整性" tabindex="-1">那么数据在进行逻辑备份的过程中，数据库中的数据就是不会发生变化的，这样就保证了数据的一致性和完整性 <a class="header-anchor" href="#那么数据在进行逻辑备份的过程中-数据库中的数据就是不会发生变化的-这样就保证了数据的一致性和完整性" aria-label="Permalink to &quot;那么数据在进行逻辑备份的过程中，数据库中的数据就是不会发生变化的，这样就保证了数据的一致性和完整性&quot;">​</a></h4></blockquote><h3 id="相关操作" tabindex="-1">相关操作 <a class="header-anchor" href="#相关操作" aria-label="Permalink to &quot;相关操作&quot;">​</a></h3><h4 id="_1-加全局锁" tabindex="-1">（1）加全局锁 <a class="header-anchor" href="#_1-加全局锁" aria-label="Permalink to &quot;（1）加全局锁&quot;">​</a></h4><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">flush tables </span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">with</span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;"> read</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> lock;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_2-数据备份" tabindex="-1">（2）数据备份 <a class="header-anchor" href="#_2-数据备份" aria-label="Permalink to &quot;（2）数据备份&quot;">​</a></h4><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">mysqldump </span><span style="--shiki-light:#D73A49;--shiki-dark:#ABB2BF;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">uroot </span><span style="--shiki-light:#D73A49;--shiki-dark:#ABB2BF;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">p123456 </span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">--all-databases &gt; all-databases.sql</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_3-释放锁" tabindex="-1">（3）释放锁 <a class="header-anchor" href="#_3-释放锁" aria-label="Permalink to &quot;（3）释放锁&quot;">​</a></h4><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">unlock</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> tables;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="锁特点" tabindex="-1">锁特点 <a class="header-anchor" href="#锁特点" aria-label="Permalink to &quot;锁特点&quot;">​</a></h3><h4 id="数据库中加全局锁-是一个比较重的操作-存在以下问题" tabindex="-1">数据库中加全局锁，是一个比较重的操作，存在以下问题 <a class="header-anchor" href="#数据库中加全局锁-是一个比较重的操作-存在以下问题" aria-label="Permalink to &quot;数据库中加全局锁，是一个比较重的操作，存在以下问题&quot;">​</a></h4><blockquote><h4 id="_1-如果在主库上备份-那么在备份期间都不能执行更新-业务基本上就得停摆" tabindex="-1">（1）如果在主库上备份，那么在备份期间都不能执行更新，业务基本上就得停摆 <a class="header-anchor" href="#_1-如果在主库上备份-那么在备份期间都不能执行更新-业务基本上就得停摆" aria-label="Permalink to &quot;（1）如果在主库上备份，那么在备份期间都不能执行更新，业务基本上就得停摆&quot;">​</a></h4><h4 id="_2-如果在从库上备份-那么在备份期间从库不能执行主库同步过来的二进制日志-binlog-会导致主从延迟" tabindex="-1">（2）如果在从库上备份，那么在备份期间从库不能执行主库同步过来的二进制日志（binlog），会导致主从延迟 <a class="header-anchor" href="#_2-如果在从库上备份-那么在备份期间从库不能执行主库同步过来的二进制日志-binlog-会导致主从延迟" aria-label="Permalink to &quot;（2）如果在从库上备份，那么在备份期间从库不能执行主库同步过来的二进制日志（binlog），会导致主从延迟&quot;">​</a></h4></blockquote><h4 id="在-innodb-引擎中-我们可以在备份时加上参数-single-transaction-参数来完成-不加锁的一致性数据备份" tabindex="-1">在 InnoDB 引擎中，我们可以在备份时加上参数 <span style="color:red;">--single-transaction </span>参数来完成 <span style="color:red;">不加锁的一致性数据备份</span> <a class="header-anchor" href="#在-innodb-引擎中-我们可以在备份时加上参数-single-transaction-参数来完成-不加锁的一致性数据备份" aria-label="Permalink to &quot;在 InnoDB 引擎中，我们可以在备份时加上参数 &lt;span style=&quot;color:red;&quot;&gt;--single-transaction &lt;/span&gt;参数来完成 &lt;span style=&quot;color:red;&quot;&gt;不加锁的一致性数据备份&lt;/span&gt;&quot;">​</a></h4><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">mysqldump</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">  --single-transaction</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">  -uroot</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> –p123456</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">  itcast</span><span style="--shiki-light:#D73A49;--shiki-dark:#ABB2BF;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> itcast.sql</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="表级锁" tabindex="-1">表级锁 <a class="header-anchor" href="#表级锁" aria-label="Permalink to &quot;表级锁&quot;">​</a></h2><h3 id="基本介绍-2" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍-2" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h3><blockquote><h4 id="表级锁-每次操作锁住整张表-锁定力度大-发生锁冲突的概率最高-并发度最低。应用在-myisam、innodb、bdb-等存储引擎中" tabindex="-1">表级锁， <span style="color:red;">每次操作锁住整张表</span>，锁定力度大，发生锁冲突的概率最高，并发度最低。应用在 MyISAM、InnoDB、BDB 等存储引擎中 <a class="header-anchor" href="#表级锁-每次操作锁住整张表-锁定力度大-发生锁冲突的概率最高-并发度最低。应用在-myisam、innodb、bdb-等存储引擎中" aria-label="Permalink to &quot;表级锁， &lt;span style=&quot;color:red;&quot;&gt;每次操作锁住整张表&lt;/span&gt;，锁定力度大，发生锁冲突的概率最高，并发度最低。应用在 MyISAM、InnoDB、BDB 等存储引擎中&quot;">​</a></h4></blockquote><h3 id="表锁" tabindex="-1">表锁 <a class="header-anchor" href="#表锁" aria-label="Permalink to &quot;表锁&quot;">​</a></h3><h4 id="两大分类" tabindex="-1">两大分类 <a class="header-anchor" href="#两大分类" aria-label="Permalink to &quot;两大分类&quot;">​</a></h4><blockquote><h4 id="_1-表共享读锁-read-lock" tabindex="-1">（1）表共享<span style="color:red;">读锁</span>（read lock） <a class="header-anchor" href="#_1-表共享读锁-read-lock" aria-label="Permalink to &quot;（1）表共享&lt;span style=&quot;color:red;&quot;&gt;读锁&lt;/span&gt;（read lock）&quot;">​</a></h4><h4 id="_2-表独占写锁-write-lock" tabindex="-1">（2）表独占<span style="color:red;">写锁</span>（write lock） <a class="header-anchor" href="#_2-表独占写锁-write-lock" aria-label="Permalink to &quot;（2）表独占&lt;span style=&quot;color:red;&quot;&gt;写锁&lt;/span&gt;（write lock）&quot;">​</a></h4></blockquote><h4 id="基本语法" tabindex="-1">基本语法 <a class="header-anchor" href="#基本语法" aria-label="Permalink to &quot;基本语法&quot;">​</a></h4><blockquote><h4 id="_1-加锁-lock-tables-表名-read-write" tabindex="-1">（1）加锁：lock tables 表名... read / write <a class="header-anchor" href="#_1-加锁-lock-tables-表名-read-write" aria-label="Permalink to &quot;（1）加锁：lock tables 表名... read / write&quot;">​</a></h4><h4 id="_2-释放锁-unlock-tables-客户端断开连接" tabindex="-1">（2）释放锁：unlock tables / 客户端断开连接 <a class="header-anchor" href="#_2-释放锁-unlock-tables-客户端断开连接" aria-label="Permalink to &quot;（2）释放锁：unlock tables / 客户端断开连接&quot;">​</a></h4></blockquote><h4 id="读锁" tabindex="-1">读锁 <a class="header-anchor" href="#读锁" aria-label="Permalink to &quot;读锁&quot;">​</a></h4><br><img src="'+n+'" style="width:800px;margin:0 auto;"><blockquote><h4 id="左侧为客户端一-对指定表加了读锁-不会影响右侧客户端二的读-但是会阻塞右侧客户端的写" tabindex="-1">左侧为客户端一，对指定表加了<span style="color:red;">读锁</span>，<span style="color:red;">不会影响</span>右侧客户端二的<span style="color:red;">读</span>，但是<span style="color:red;">会阻塞</span>右侧客户端的<span style="color:red;">写</span> <a class="header-anchor" href="#左侧为客户端一-对指定表加了读锁-不会影响右侧客户端二的读-但是会阻塞右侧客户端的写" aria-label="Permalink to &quot;左侧为客户端一，对指定表加了&lt;span style=&quot;color:red;&quot;&gt;读锁&lt;/span&gt;，&lt;span style=&quot;color:red;&quot;&gt;不会影响&lt;/span&gt;右侧客户端二的&lt;span style=&quot;color:red;&quot;&gt;读&lt;/span&gt;，但是&lt;span style=&quot;color:red;&quot;&gt;会阻塞&lt;/span&gt;右侧客户端的&lt;span style=&quot;color:red;&quot;&gt;写&lt;/span&gt;&quot;">​</a></h4></blockquote><h5 id="写锁" tabindex="-1">写锁 <a class="header-anchor" href="#写锁" aria-label="Permalink to &quot;写锁&quot;">​</a></h5><br><img src="'+i+'" style="width:800px;margin:0 auto;"><blockquote><h4 id="左侧为客户端一-对指定表加了写锁-会阻塞右侧客户端的读和写" tabindex="-1">左侧为客户端一，对指定表加了<span style="color:red;">写锁</span>，<span style="color:red;">会阻塞</span>右侧客户端的<span style="color:red;">读和写</span> <a class="header-anchor" href="#左侧为客户端一-对指定表加了写锁-会阻塞右侧客户端的读和写" aria-label="Permalink to &quot;左侧为客户端一，对指定表加了&lt;span style=&quot;color:red;&quot;&gt;写锁&lt;/span&gt;，&lt;span style=&quot;color:red;&quot;&gt;会阻塞&lt;/span&gt;右侧客户端的&lt;span style=&quot;color:red;&quot;&gt;读和写&lt;/span&gt;&quot;">​</a></h4></blockquote><div class="tip custom-block"><p class="custom-block-title"><span style="font-size:18px;font-weight:bold;">⭐ 结论</span></p><h4 id="_1-读锁不会阻塞其他客户端的读-但是会阻塞写" tabindex="-1">（1）<span style="color:red;">读锁</span>不会阻塞其他客户端的读，但是会阻塞写 <a class="header-anchor" href="#_1-读锁不会阻塞其他客户端的读-但是会阻塞写" aria-label="Permalink to &quot;（1）&lt;span style=&quot;color:red;&quot;&gt;读锁&lt;/span&gt;不会阻塞其他客户端的读，但是会阻塞写&quot;">​</a></h4><h4 id="_2-写锁既会阻塞其他客户端的读-又会阻塞其他客户端的写" tabindex="-1">（2）<span style="color:red;">写锁</span>既会阻塞其他客户端的读，又会阻塞其他客户端的写 <a class="header-anchor" href="#_2-写锁既会阻塞其他客户端的读-又会阻塞其他客户端的写" aria-label="Permalink to &quot;（2）&lt;span style=&quot;color:red;&quot;&gt;写锁&lt;/span&gt;既会阻塞其他客户端的读，又会阻塞其他客户端的写&quot;">​</a></h4></div><h3 id="元数据锁" tabindex="-1">元数据锁 <a class="header-anchor" href="#元数据锁" aria-label="Permalink to &quot;元数据锁&quot;">​</a></h3><h4 id="基本介绍-3" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍-3" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h4><blockquote><h4 id="meta-data-lock-元数据锁-简写mdl-mdl-加锁过程是系统自动控制-无需显式使用-在访问一张表的时候会自动加上" tabindex="-1">meta data lock，元数据锁，简写<span style="color:red;">MDL</span>，MDL 加锁过程是系统自动控制，无需显式使用，<span style="color:red;">在访问一张表的时候会自动加上</span> <a class="header-anchor" href="#meta-data-lock-元数据锁-简写mdl-mdl-加锁过程是系统自动控制-无需显式使用-在访问一张表的时候会自动加上" aria-label="Permalink to &quot;meta data lock，元数据锁，简写&lt;span style=&quot;color:red;&quot;&gt;MDL&lt;/span&gt;，MDL 加锁过程是系统自动控制，无需显式使用，&lt;span style=&quot;color:red;&quot;&gt;在访问一张表的时候会自动加上&lt;/span&gt;&quot;">​</a></h4></blockquote><h4 id="mdl-锁主要作用是" tabindex="-1">MDL 锁主要作用是 <a class="header-anchor" href="#mdl-锁主要作用是" aria-label="Permalink to &quot;MDL 锁主要作用是&quot;">​</a></h4><blockquote><h4 id="维护表元数据的数据一致性-在表上有活动事务的时候-不可以对元数据进行写入操作。为了避免-dml-与-ddl-冲突-保证读写的正确性" tabindex="-1">维护表元数据的数据一致性，在表上<span style="color:red;">有活动事务</span>的时候，<span style="color:red;">不可以</span>对元数据进行<span style="color:red;">写入</span>操作。为了<span style="color:red;">避免 DML 与 DDL 冲突</span>，保证读写的正确性 <a class="header-anchor" href="#维护表元数据的数据一致性-在表上有活动事务的时候-不可以对元数据进行写入操作。为了避免-dml-与-ddl-冲突-保证读写的正确性" aria-label="Permalink to &quot;维护表元数据的数据一致性，在表上&lt;span style=&quot;color:red;&quot;&gt;有活动事务&lt;/span&gt;的时候，&lt;span style=&quot;color:red;&quot;&gt;不可以&lt;/span&gt;对元数据进行&lt;span style=&quot;color:red;&quot;&gt;写入&lt;/span&gt;操作。为了&lt;span style=&quot;color:red;&quot;&gt;避免 DML 与 DDL 冲突&lt;/span&gt;，保证读写的正确性&quot;">​</a></h4></blockquote><h4 id="这里的元数据-大家可以简单理解为就是一张表的表结构-也就是说-某一张表涉及到未提交的事务时-是不能够修改这张表的表结构的" tabindex="-1">这里的元数据，大家可以简单理解为就是一张表的表结构，也就是说，某一张表涉及到<span style="color:red;">未提交的事务</span>时，是<span style="color:red;">不能够修改这张表的表结构</span>的 <a class="header-anchor" href="#这里的元数据-大家可以简单理解为就是一张表的表结构-也就是说-某一张表涉及到未提交的事务时-是不能够修改这张表的表结构的" aria-label="Permalink to &quot;这里的元数据，大家可以简单理解为就是一张表的表结构，也就是说，某一张表涉及到&lt;span style=&quot;color:red;&quot;&gt;未提交的事务&lt;/span&gt;时，是&lt;span style=&quot;color:red;&quot;&gt;不能够修改这张表的表结构&lt;/span&gt;的&quot;">​</a></h4><div class="tip custom-block"><p class="custom-block-title"><span style="font-size:18px;font-weight:bold;">💡 Tip</span></p><h4 id="在-mysql5-5-中引入了-mdl-当对一张表进行增删改查的时候-加-mdl-读锁-read-共享锁-当对表结构进行变更操作的时候-加-mdl-写锁-write-排他锁-共享锁与排他锁互斥" tabindex="-1">在 MySQL5.5 中引入了 MDL，当对一张表进行<span style="color:red;">增删改查</span>的时候，加 MDL <span style="color:red;">读锁 read</span>（<span style="color:red;">共享锁</span>），当对<span style="color:red;">表结构进行变更</span>操作的时候，加 MDL <span style="color:red;">写锁 write</span>（<span style="color:red;">排他锁</span>），<span style="color:red;">共享锁与排他锁互斥</span> <a class="header-anchor" href="#在-mysql5-5-中引入了-mdl-当对一张表进行增删改查的时候-加-mdl-读锁-read-共享锁-当对表结构进行变更操作的时候-加-mdl-写锁-write-排他锁-共享锁与排他锁互斥" aria-label="Permalink to &quot;在 MySQL5.5 中引入了 MDL，当对一张表进行&lt;span style=&quot;color:red;&quot;&gt;增删改查&lt;/span&gt;的时候，加 MDL &lt;span style=&quot;color:red;&quot;&gt;读锁 read&lt;/span&gt;（&lt;span style=&quot;color:red;&quot;&gt;共享锁&lt;/span&gt;），当对&lt;span style=&quot;color:red;&quot;&gt;表结构进行变更&lt;/span&gt;操作的时候，加 MDL &lt;span style=&quot;color:red;&quot;&gt;写锁 write&lt;/span&gt;（&lt;span style=&quot;color:red;&quot;&gt;排他锁&lt;/span&gt;），&lt;span style=&quot;color:red;&quot;&gt;共享锁与排他锁互斥&lt;/span&gt;&quot;">​</a></h4></div><h4 id="锁类型" tabindex="-1">锁类型 <a class="header-anchor" href="#锁类型" aria-label="Permalink to &quot;锁类型&quot;">​</a></h4><br><img src="'+d+'" style="width:800px;margin:0 auto;"><h4 id="当执行-select、insert、update、delete-等语句时-添加的是元数据共享锁-shared-read-shared-write-之间是兼容的" tabindex="-1">当执行 SELECT、INSERT、UPDATE、DELETE 等语句时，添加的是元数据<span style="color:red;">共享锁</span>（<span style="color:red;">SHARED_READ / SHARED_WRITE</span>），之间是<span style="color:red;">兼容</span>的 <a class="header-anchor" href="#当执行-select、insert、update、delete-等语句时-添加的是元数据共享锁-shared-read-shared-write-之间是兼容的" aria-label="Permalink to &quot;当执行 SELECT、INSERT、UPDATE、DELETE 等语句时，添加的是元数据&lt;span style=&quot;color:red;&quot;&gt;共享锁&lt;/span&gt;（&lt;span style=&quot;color:red;&quot;&gt;SHARED_READ / SHARED_WRITE&lt;/span&gt;），之间是&lt;span style=&quot;color:red;&quot;&gt;兼容&lt;/span&gt;的&quot;">​</a></h4><br><img src="'+h+'" style="width:800px;margin:0 auto;"><h4 id="当执行-select-语句时-添加的是元数据共享锁-shared-read-会阻塞元数据排他锁-exclusive-之间是互斥的" tabindex="-1">当执行 SELECT 语句时，添加的是元数据共享锁（<span style="color:red;">SHARED_READ</span>），会阻塞元数据排他锁（<span style="color:red;">EXCLUSIVE</span>），之间是<span style="color:red;">互斥</span>的 <a class="header-anchor" href="#当执行-select-语句时-添加的是元数据共享锁-shared-read-会阻塞元数据排他锁-exclusive-之间是互斥的" aria-label="Permalink to &quot;当执行 SELECT 语句时，添加的是元数据共享锁（&lt;span style=&quot;color:red;&quot;&gt;SHARED_READ&lt;/span&gt;），会阻塞元数据排他锁（&lt;span style=&quot;color:red;&quot;&gt;EXCLUSIVE&lt;/span&gt;），之间是&lt;span style=&quot;color:red;&quot;&gt;互斥&lt;/span&gt;的&quot;">​</a></h4><br><img src="'+c+`" style="width:800px;margin:0 auto;"><h4 id="⭐-查看元数据锁" tabindex="-1">⭐ 查看元数据锁 <a class="header-anchor" href="#⭐-查看元数据锁" aria-label="Permalink to &quot;⭐ 查看元数据锁&quot;">​</a></h4><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> object_type,object_schema,object_name,lock_type,lock_duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">from</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">performance_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">metadata_locks</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> ;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="意向锁" tabindex="-1">意向锁 <a class="header-anchor" href="#意向锁" aria-label="Permalink to &quot;意向锁&quot;">​</a></h3><h4 id="基本介绍-4" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍-4" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h4><blockquote><h4 id="为了避免dml-在执行时-加的行锁与表锁的冲突-在-innodb-中引入了意向锁-使得表锁不用检查每行数据是否加锁-使用意向锁来减少表锁的检查" tabindex="-1">为了<span style="color:red;">避免</span>DML 在执行时，加的<span style="color:red;">行锁与表锁的冲突</span>，在 InnoDB 中引入了意向锁，使得表锁不用检查每行数据是否加锁，使用意向锁来<span style="color:red;">减少表锁的检查</span> <a class="header-anchor" href="#为了避免dml-在执行时-加的行锁与表锁的冲突-在-innodb-中引入了意向锁-使得表锁不用检查每行数据是否加锁-使用意向锁来减少表锁的检查" aria-label="Permalink to &quot;为了&lt;span style=&quot;color:red;&quot;&gt;避免&lt;/span&gt;DML 在执行时，加的&lt;span style=&quot;color:red;&quot;&gt;行锁与表锁的冲突&lt;/span&gt;，在 InnoDB 中引入了意向锁，使得表锁不用检查每行数据是否加锁，使用意向锁来&lt;span style=&quot;color:red;&quot;&gt;减少表锁的检查&lt;/span&gt;&quot;">​</a></h4></blockquote><h4 id="没有意向锁的情况分析" tabindex="-1">没有意向锁的情况分析 <a class="header-anchor" href="#没有意向锁的情况分析" aria-label="Permalink to &quot;没有意向锁的情况分析&quot;">​</a></h4><h4 id="_1-首先客户端一-开启一个事务-然后执行-dml-操作-在执行-dml-语句时-会对涉及到的行加行锁" tabindex="-1">（1）首先客户端一，开启一个事务，然后执行 DML 操作，在执行 DML 语句时，会对涉及到的行加行锁 <a class="header-anchor" href="#_1-首先客户端一-开启一个事务-然后执行-dml-操作-在执行-dml-语句时-会对涉及到的行加行锁" aria-label="Permalink to &quot;（1）首先客户端一，开启一个事务，然后执行 DML 操作，在执行 DML 语句时，会对涉及到的行加行锁&quot;">​</a></h4><br><img src="`+p+'" style="width:800px;margin:0 auto;"><h4 id="_2-当客户端二-想对这张表加表锁时-会检查当前表是否有对应的行锁-如果没有-则添加表锁-此时就会从第一行数据-检查到最后一行数据-效率较低" tabindex="-1">（2）当客户端二，<span style="color:red;">想对这张表加表锁时，会检查当前表是否有对应的行锁</span>，如果没有，则添加表锁，此时就会从第一行数据，检查到最后一行数据，效率较低 <a class="header-anchor" href="#_2-当客户端二-想对这张表加表锁时-会检查当前表是否有对应的行锁-如果没有-则添加表锁-此时就会从第一行数据-检查到最后一行数据-效率较低" aria-label="Permalink to &quot;（2）当客户端二，&lt;span style=&quot;color:red;&quot;&gt;想对这张表加表锁时，会检查当前表是否有对应的行锁&lt;/span&gt;，如果没有，则添加表锁，此时就会从第一行数据，检查到最后一行数据，效率较低&quot;">​</a></h4><br><img src="'+u+'" style="width:800px;margin:0 auto;"><h4 id="加了意向锁" tabindex="-1">加了意向锁 <a class="header-anchor" href="#加了意向锁" aria-label="Permalink to &quot;加了意向锁&quot;">​</a></h4><h4 id="_1-客户端一-在执行-dml-操作时-会对涉及的行加行锁-同时也会对该表加上意向锁" tabindex="-1">（1）客户端一，在执行 DML 操作时，会对涉及的行加行锁，同时也会对该表加上意向锁 <a class="header-anchor" href="#_1-客户端一-在执行-dml-操作时-会对涉及的行加行锁-同时也会对该表加上意向锁" aria-label="Permalink to &quot;（1）客户端一，在执行 DML 操作时，会对涉及的行加行锁，同时也会对该表加上意向锁&quot;">​</a></h4><br><img src="'+q+'" style="width:800px;margin:0 auto;"><h4 id="_2-而其他客户端-在对这张表加表锁的时候-会根据该表上所加的意向锁来判定是否可以成功加表锁-而不用逐行判断行锁情况了" tabindex="-1">（2）而其他客户端，在对这张表加表锁的时候，会<span style="color:red;">根据该表上所加的意向锁来判定是否可以成功加表锁</span>，而不用逐行判断行锁情况了 <a class="header-anchor" href="#_2-而其他客户端-在对这张表加表锁的时候-会根据该表上所加的意向锁来判定是否可以成功加表锁-而不用逐行判断行锁情况了" aria-label="Permalink to &quot;（2）而其他客户端，在对这张表加表锁的时候，会&lt;span style=&quot;color:red;&quot;&gt;根据该表上所加的意向锁来判定是否可以成功加表锁&lt;/span&gt;，而不用逐行判断行锁情况了&quot;">​</a></h4><br><img src="'+b+'" style="width:800px;margin:0 auto;"><h4 id="锁分类" tabindex="-1">锁分类 <a class="header-anchor" href="#锁分类" aria-label="Permalink to &quot;锁分类&quot;">​</a></h4><blockquote><h4 id="_1-意向共享锁-is-由语句-select-lock-in-share-mode-添加-与表锁共享锁-read-兼容-与表锁排他锁-write-互斥" tabindex="-1">（1）意向共享锁（IS）: 由语句 <span style="color:red;">select ... lock in share mode</span> 添加，与表锁共享锁（<span style="color:red;">read</span>）<span style="color:red;">兼容</span>，与表锁排他锁（<span style="color:red;">write</span>）<span style="color:red;">互斥</span> <a class="header-anchor" href="#_1-意向共享锁-is-由语句-select-lock-in-share-mode-添加-与表锁共享锁-read-兼容-与表锁排他锁-write-互斥" aria-label="Permalink to &quot;（1）意向共享锁（IS）: 由语句 &lt;span style=&quot;color:red;&quot;&gt;select ... lock in share mode&lt;/span&gt; 添加，与表锁共享锁（&lt;span style=&quot;color:red;&quot;&gt;read&lt;/span&gt;）&lt;span style=&quot;color:red;&quot;&gt;兼容&lt;/span&gt;，与表锁排他锁（&lt;span style=&quot;color:red;&quot;&gt;write&lt;/span&gt;）&lt;span style=&quot;color:red;&quot;&gt;互斥&lt;/span&gt;&quot;">​</a></h4><h4 id="_2-意向排他锁-ix-由-insert、update、delete、select-for-update-添加-与表锁共享锁-read-及排他锁-write-都互斥" tabindex="-1">（2）意向排他锁（IX）: 由 <span style="color:red;">insert、update、delete、select...for update</span> 添加，与表锁共享锁（<span style="color:red;">read</span>）及排他锁（<span style="color:red;">write</span>）<span style="color:red;">都互斥</span> <a class="header-anchor" href="#_2-意向排他锁-ix-由-insert、update、delete、select-for-update-添加-与表锁共享锁-read-及排他锁-write-都互斥" aria-label="Permalink to &quot;（2）意向排他锁（IX）: 由 &lt;span style=&quot;color:red;&quot;&gt;insert、update、delete、select...for update&lt;/span&gt; 添加，与表锁共享锁（&lt;span style=&quot;color:red;&quot;&gt;read&lt;/span&gt;）及排他锁（&lt;span style=&quot;color:red;&quot;&gt;write&lt;/span&gt;）&lt;span style=&quot;color:red;&quot;&gt;都互斥&lt;/span&gt;&quot;">​</a></h4></blockquote><div class="tip custom-block"><p class="custom-block-title"><span style="font-size:18px;font-weight:bold;">💡 Tip</span></p><h4 id="_1-意向锁之间不会互斥" tabindex="-1">（1）<span style="color:red;">意向锁之间不会互斥</span> <a class="header-anchor" href="#_1-意向锁之间不会互斥" aria-label="Permalink to &quot;（1）&lt;span style=&quot;color:red;&quot;&gt;意向锁之间不会互斥&lt;/span&gt;&quot;">​</a></h4><h4 id="_2-一旦事务提交了-意向共享锁、意向排他锁-都会自动释放" tabindex="-1">（2）一旦事务提交了，意向共享锁、意向排他锁，都会自动释放 <a class="header-anchor" href="#_2-一旦事务提交了-意向共享锁、意向排他锁-都会自动释放" aria-label="Permalink to &quot;（2）一旦事务提交了，意向共享锁、意向排他锁，都会自动释放&quot;">​</a></h4></div><h4 id="意向共享锁与表读锁是兼容的" tabindex="-1">意向共享锁与表读锁是兼容的 <a class="header-anchor" href="#意向共享锁与表读锁是兼容的" aria-label="Permalink to &quot;意向共享锁与表读锁是兼容的&quot;">​</a></h4><br><img src="'+k+'" style="width:800px;margin:0 auto;"><h4 id="意向排他锁与表读锁-read-、写锁-write-都是互斥的" tabindex="-1">意向排他锁与表读锁（read）、写锁（write）都是互斥的 <a class="header-anchor" href="#意向排他锁与表读锁-read-、写锁-write-都是互斥的" aria-label="Permalink to &quot;意向排他锁与表读锁（read）、写锁（write）都是互斥的&quot;">​</a></h4><br><img src="'+g+'" style="width:800px;margin:0 auto;"><h2 id="行级锁" tabindex="-1">行级锁 <a class="header-anchor" href="#行级锁" aria-label="Permalink to &quot;行级锁&quot;">​</a></h2><h3 id="基本介绍-5" tabindex="-1">基本介绍 <a class="header-anchor" href="#基本介绍-5" aria-label="Permalink to &quot;基本介绍&quot;">​</a></h3><blockquote><h4 id="行级锁-每次操作锁住对应的行数据。锁定力度最小-发生锁冲突的概率最低-并发度最高-应用在-innodb-存储引擎中" tabindex="-1">行级锁，每次操作<span style="color:red;">锁住对应的行数据</span>。锁定力度最小，发生锁冲突的概率最低，并发度最高，应用在 InnoDB 存储引擎中 <a class="header-anchor" href="#行级锁-每次操作锁住对应的行数据。锁定力度最小-发生锁冲突的概率最低-并发度最高-应用在-innodb-存储引擎中" aria-label="Permalink to &quot;行级锁，每次操作&lt;span style=&quot;color:red;&quot;&gt;锁住对应的行数据&lt;/span&gt;。锁定力度最小，发生锁冲突的概率最低，并发度最高，应用在 InnoDB 存储引擎中&quot;">​</a></h4></blockquote><h4 id="innodb-的数据是基于索引组织的-行锁是通过对索引上的索引项加锁来实现的-而不是对记录加的锁。对于行级锁-主要分为以下三类" tabindex="-1">InnoDB 的数据是基于索引组织的，行锁是通过对索引上的索引项加锁来实现的，而不是对记录加的锁。对于行级锁，主要分为以下三类 <a class="header-anchor" href="#innodb-的数据是基于索引组织的-行锁是通过对索引上的索引项加锁来实现的-而不是对记录加的锁。对于行级锁-主要分为以下三类" aria-label="Permalink to &quot;InnoDB 的数据是基于索引组织的，行锁是通过对索引上的索引项加锁来实现的，而不是对记录加的锁。对于行级锁，主要分为以下三类&quot;">​</a></h4><br><img src="'+m+'" style="width:800px;margin:0 auto;"><div class="tip custom-block"><p class="custom-block-title"><span style="font-size:18px;font-weight:bold;">⚠️ 注意</span></p><h4 id="对-id-34-的记录加间隙锁-这个锁是对-5-之前的间隙加锁" tabindex="-1">对 id = 34 的记录加<span style="color:red;">间隙锁</span>，这个锁是对 5 <span style="color:red;">之前</span>的间隙加锁 <a class="header-anchor" href="#对-id-34-的记录加间隙锁-这个锁是对-5-之前的间隙加锁" aria-label="Permalink to &quot;对 id = 34 的记录加&lt;span style=&quot;color:red;&quot;&gt;间隙锁&lt;/span&gt;，这个锁是对 5 &lt;span style=&quot;color:red;&quot;&gt;之前&lt;/span&gt;的间隙加锁&quot;">​</a></h4></div><h3 id="行锁" tabindex="-1">行锁 <a class="header-anchor" href="#行锁" aria-label="Permalink to &quot;行锁&quot;">​</a></h3><h4 id="两大分类-1" tabindex="-1">两大分类 <a class="header-anchor" href="#两大分类-1" aria-label="Permalink to &quot;两大分类&quot;">​</a></h4><blockquote><h4 id="_1-共享锁-s-允许一个事务去读一行-阻止其他事务获得相同数据集的排它锁" tabindex="-1">（1）共享锁（S）：允许一个事务去读一行，阻止其他事务获得相同数据集的排它锁 <a class="header-anchor" href="#_1-共享锁-s-允许一个事务去读一行-阻止其他事务获得相同数据集的排它锁" aria-label="Permalink to &quot;（1）共享锁（S）：允许一个事务去读一行，阻止其他事务获得相同数据集的排它锁&quot;">​</a></h4><h4 id="_2-排他锁-x-允许获取排他锁的事务更新数据-阻止其他事务获得相同数据集的共享锁和排他锁" tabindex="-1">（2）排他锁（X）：允许获取排他锁的事务更新数据，阻止其他事务获得相同数据集的共享锁和排他锁 <a class="header-anchor" href="#_2-排他锁-x-允许获取排他锁的事务更新数据-阻止其他事务获得相同数据集的共享锁和排他锁" aria-label="Permalink to &quot;（2）排他锁（X）：允许获取排他锁的事务更新数据，阻止其他事务获得相同数据集的共享锁和排他锁&quot;">​</a></h4></blockquote><br><img src="'+y+'" style="width:800px;margin:0 auto;"><h4 id="常见的-sql-语句-在执行时-所加的行锁如下" tabindex="-1">常见的 SQL 语句，在执行时，所加的行锁如下 <a class="header-anchor" href="#常见的-sql-语句-在执行时-所加的行锁如下" aria-label="Permalink to &quot;常见的 SQL 语句，在执行时，所加的行锁如下&quot;">​</a></h4><br><img src="'+_+`" style="width:800px;margin:0 auto;"><h4 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><h4 id="默认情况下-innodb-在-repeatable-read-事务隔离级别运行-innodb-使用-next-key-锁进行搜索和索引扫描-以防止幻读" tabindex="-1"><span style="color:red;">默认</span>情况下，InnoDB 在 <span style="color:red;">REPEATABLE READ</span> 事务隔离级别运行，InnoDB 使用 next-key 锁进行搜索和索引扫描，以<span style="color:red;">防止幻读</span> <a class="header-anchor" href="#默认情况下-innodb-在-repeatable-read-事务隔离级别运行-innodb-使用-next-key-锁进行搜索和索引扫描-以防止幻读" aria-label="Permalink to &quot;&lt;span style=&quot;color:red;&quot;&gt;默认&lt;/span&gt;情况下，InnoDB 在 &lt;span style=&quot;color:red;&quot;&gt;REPEATABLE READ&lt;/span&gt; 事务隔离级别运行，InnoDB 使用 next-key 锁进行搜索和索引扫描，以&lt;span style=&quot;color:red;&quot;&gt;防止幻读&lt;/span&gt;&quot;">​</a></h4><blockquote><h4 id="_1-针对唯一索引进行检索时-对已存在的记录进行等值匹配时-将会自动优化为行锁" tabindex="-1">（1）针对<span style="color:red;">唯一索引</span>进行检索时，对已存在的记录进行<span style="color:red;">等值匹配</span>时，将会<span style="color:red;">自动优化为行锁</span> <a class="header-anchor" href="#_1-针对唯一索引进行检索时-对已存在的记录进行等值匹配时-将会自动优化为行锁" aria-label="Permalink to &quot;（1）针对&lt;span style=&quot;color:red;&quot;&gt;唯一索引&lt;/span&gt;进行检索时，对已存在的记录进行&lt;span style=&quot;color:red;&quot;&gt;等值匹配&lt;/span&gt;时，将会&lt;span style=&quot;color:red;&quot;&gt;自动优化为行锁&lt;/span&gt;&quot;">​</a></h4><h4 id="_2-innodb-的行锁是针对于索引加的锁-不通过索引条件检索数据-那么-innodb-将对表中的所有记录加锁-此时就会升级为表锁" tabindex="-1">（2）InnoDB 的<span style="color:red;">行锁是针对于索引加的锁</span>，<span style="color:red;">不通过索引</span>条件检索数据，那么 InnoDB 将对表中的所有记录加锁，此时就<span style="color:red;">会升级为表锁</span> <a class="header-anchor" href="#_2-innodb-的行锁是针对于索引加的锁-不通过索引条件检索数据-那么-innodb-将对表中的所有记录加锁-此时就会升级为表锁" aria-label="Permalink to &quot;（2）InnoDB 的&lt;span style=&quot;color:red;&quot;&gt;行锁是针对于索引加的锁&lt;/span&gt;，&lt;span style=&quot;color:red;&quot;&gt;不通过索引&lt;/span&gt;条件检索数据，那么 InnoDB 将对表中的所有记录加锁，此时就&lt;span style=&quot;color:red;&quot;&gt;会升级为表锁&lt;/span&gt;&quot;">​</a></h4></blockquote><h4 id="⭐-查看意向锁及行锁的加锁情况" tabindex="-1">⭐ 查看意向锁及行锁的加锁情况 <a class="header-anchor" href="#⭐-查看意向锁及行锁的加锁情况" aria-label="Permalink to &quot;⭐ 查看意向锁及行锁的加锁情况&quot;">​</a></h4><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> object_schema,object_name,index_name,lock_type,lock_mode,lock_data </span><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">from</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">performance_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">data_locks</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="间隙锁-临键锁" tabindex="-1">间隙锁&amp;临键锁 <a class="header-anchor" href="#间隙锁-临键锁" aria-label="Permalink to &quot;间隙锁&amp;临键锁&quot;">​</a></h3><h4 id="默认情况下-innodb-在-repeatable-read-事务隔离级别运行-innodb-使用-next-key-锁进行搜索和索引扫描-以防止幻读-1" tabindex="-1"><span style="color:red;">默认</span>情况下，InnoDB 在 <span style="color:red;">REPEATABLE READ</span> 事务隔离级别运行，InnoDB 使用 next-key 锁进行搜索和索引扫描，以防止幻读 <a class="header-anchor" href="#默认情况下-innodb-在-repeatable-read-事务隔离级别运行-innodb-使用-next-key-锁进行搜索和索引扫描-以防止幻读-1" aria-label="Permalink to &quot;&lt;span style=&quot;color:red;&quot;&gt;默认&lt;/span&gt;情况下，InnoDB 在 &lt;span style=&quot;color:red;&quot;&gt;REPEATABLE READ&lt;/span&gt; 事务隔离级别运行，InnoDB 使用 next-key 锁进行搜索和索引扫描，以防止幻读&quot;">​</a></h4><blockquote><h4 id="_1-索引上的等值查询-唯一索引-给不存在的记录加锁时-优化为间隙锁" tabindex="-1">（1）索引上的<span style="color:red;">等值</span>查询（<span style="color:red;">唯一索引</span>），给不存在的记录加锁时，优化为间隙锁 <a class="header-anchor" href="#_1-索引上的等值查询-唯一索引-给不存在的记录加锁时-优化为间隙锁" aria-label="Permalink to &quot;（1）索引上的&lt;span style=&quot;color:red;&quot;&gt;等值&lt;/span&gt;查询（&lt;span style=&quot;color:red;&quot;&gt;唯一索引&lt;/span&gt;），给不存在的记录加锁时，优化为间隙锁&quot;">​</a></h4><h4 id="_2-索引上的等值查询-非唯一普通索引-向右遍历时最后一个值不满足查询需求时-next-key-lock-退化为间隙锁" tabindex="-1">（2）索引上的<span style="color:red;">等值</span>查询（<span style="color:red;">非唯一普通索引</span>），向右遍历时最后一个值不满足查询需求时，next-key lock 退化为间隙锁 <a class="header-anchor" href="#_2-索引上的等值查询-非唯一普通索引-向右遍历时最后一个值不满足查询需求时-next-key-lock-退化为间隙锁" aria-label="Permalink to &quot;（2）索引上的&lt;span style=&quot;color:red;&quot;&gt;等值&lt;/span&gt;查询（&lt;span style=&quot;color:red;&quot;&gt;非唯一普通索引&lt;/span&gt;），向右遍历时最后一个值不满足查询需求时，next-key lock 退化为间隙锁&quot;">​</a></h4><h4 id="_3-索引上的范围查询-唯一索引-会访问到不满足条件的第一个值为止" tabindex="-1">（3）索引上的<span style="color:red;">范围</span>查询（<span style="color:red;">唯一索引</span>），会访问到不满足条件的第一个值为止 <a class="header-anchor" href="#_3-索引上的范围查询-唯一索引-会访问到不满足条件的第一个值为止" aria-label="Permalink to &quot;（3）索引上的&lt;span style=&quot;color:red;&quot;&gt;范围&lt;/span&gt;查询（&lt;span style=&quot;color:red;&quot;&gt;唯一索引&lt;/span&gt;），会访问到不满足条件的第一个值为止&quot;">​</a></h4></blockquote><div class="tip custom-block"><p class="custom-block-title"><span style="font-size:18px;font-weight:bold;">⚠️ 注意</span></p><h4 id="间隙锁唯一目的是防止其他事务插入间隙-间隙锁可以共存-一个事务采用的间隙锁不会阻止另一个事务在同一间隙上采用间隙锁" tabindex="-1">间隙锁唯一目的是防止其他事务插入间隙，<span style="color:red;">间隙锁可以共存</span>，一个事务采用的间隙锁不会阻止另一个事务在同一间隙上采用间隙锁 <a class="header-anchor" href="#间隙锁唯一目的是防止其他事务插入间隙-间隙锁可以共存-一个事务采用的间隙锁不会阻止另一个事务在同一间隙上采用间隙锁" aria-label="Permalink to &quot;间隙锁唯一目的是防止其他事务插入间隙，&lt;span style=&quot;color:red;&quot;&gt;间隙锁可以共存&lt;/span&gt;，一个事务采用的间隙锁不会阻止另一个事务在同一间隙上采用间隙锁&quot;">​</a></h4></div><h4 id="索引上的等值查询-唯一索引-给不存在的记录加锁时-优化为间隙锁" tabindex="-1">索引上的等值查询(唯一索引)，给不存在的记录加锁时, 优化为间隙锁 <a class="header-anchor" href="#索引上的等值查询-唯一索引-给不存在的记录加锁时-优化为间隙锁" aria-label="Permalink to &quot;索引上的等值查询(唯一索引)，给不存在的记录加锁时, 优化为间隙锁&quot;">​</a></h4><br><img src="`+x+'" style="width:800px;margin:0 auto;"><h4 id="索引上的等值查询-非唯一普通索引-向右遍历时最后一个值不满足查询需求时-next-key-lock-退化为间隙锁" tabindex="-1">索引上的等值查询（非唯一普通索引），向右遍历时最后一个值不满足查询需求时，next-key lock 退化为间隙锁 <a class="header-anchor" href="#索引上的等值查询-非唯一普通索引-向右遍历时最后一个值不满足查询需求时-next-key-lock-退化为间隙锁" aria-label="Permalink to &quot;索引上的等值查询（非唯一普通索引），向右遍历时最后一个值不满足查询需求时，next-key lock 退化为间隙锁&quot;">​</a></h4><blockquote><h4 id="我们知道-innodb-的-b-树索引-叶子节点是有序的双向链表。-假如-我们要根据这个二级索引查询值为-18-的数据-并加上共享锁-我们是只锁定-18-这一行就可以了吗-并不是-因为是非唯一索引-这个结构中可能有多个-18-的存在-所以-在加锁时会继续往后找-找到一个不满足条件的值-当前案例中也就是-29-。此时会对-18-加临键锁-并对-29-之前的间隙加锁" tabindex="-1">我们知道 InnoDB 的 B+树索引，叶子节点是有序的双向链表。 假如，我们要根据这个二级索引查询值为 18 的数据，并加上共享锁，我们是只锁定 18 这一行就可以了吗？ 并不是，因为是非唯一索引，这个结构中可能有多个 18 的存在，所以，在加锁时会继续往后找，找到一个不满足条件的值（当前案例中也就是 29）。此时会<span style="color:red;">对 18 加临键锁，并对 29 之前的间隙加锁</span> <a class="header-anchor" href="#我们知道-innodb-的-b-树索引-叶子节点是有序的双向链表。-假如-我们要根据这个二级索引查询值为-18-的数据-并加上共享锁-我们是只锁定-18-这一行就可以了吗-并不是-因为是非唯一索引-这个结构中可能有多个-18-的存在-所以-在加锁时会继续往后找-找到一个不满足条件的值-当前案例中也就是-29-。此时会对-18-加临键锁-并对-29-之前的间隙加锁" aria-label="Permalink to &quot;我们知道 InnoDB 的 B+树索引，叶子节点是有序的双向链表。 假如，我们要根据这个二级索引查询值为 18 的数据，并加上共享锁，我们是只锁定 18 这一行就可以了吗？ 并不是，因为是非唯一索引，这个结构中可能有多个 18 的存在，所以，在加锁时会继续往后找，找到一个不满足条件的值（当前案例中也就是 29）。此时会&lt;span style=&quot;color:red&quot;&gt;对 18 加临键锁，并对 29 之前的间隙加锁&lt;/span&gt;&quot;">​</a></h4></blockquote><br><img src="'+f+'" style="width:800px;margin:0 auto;"><h4 id="索引上的范围查询-唯一索引-会访问到不满足条件的第一个值为止" tabindex="-1">索引上的范围查询（唯一索引），会访问到不满足条件的第一个值为止 <a class="header-anchor" href="#索引上的范围查询-唯一索引-会访问到不满足条件的第一个值为止" aria-label="Permalink to &quot;索引上的范围查询（唯一索引），会访问到不满足条件的第一个值为止&quot;">​</a></h4><blockquote><h4 id="查询的条件为-id-19-并添加共享锁-此时我们可以根据数据库表中现有的数据-将数据分为三个部分-19-、-19-25-、-25-∞" tabindex="-1">查询的条件为 id &gt;= 19，并添加共享锁，此时我们可以根据数据库表中现有的数据，将数据分为三个部分：[19]、(19,25]、(25,+∞] <a class="header-anchor" href="#查询的条件为-id-19-并添加共享锁-此时我们可以根据数据库表中现有的数据-将数据分为三个部分-19-、-19-25-、-25-∞" aria-label="Permalink to &quot;查询的条件为 id &gt;= 19，并添加共享锁，此时我们可以根据数据库表中现有的数据，将数据分为三个部分：[19]、(19,25]、(25,+∞]&quot;">​</a></h4><h4 id="所以数据库数据在加锁是-就是将-19-加了行锁-25-的临键锁-包含-25-及-25-之前的间隙-正无穷的临键锁-正无穷及之前的间隙" tabindex="-1">所以数据库数据在加锁是，就是将 19 加了行锁，25 的临键锁（包含 25 及 25 <span style="color:red;">之前</span>的间隙），正无穷的临键锁（正无穷及之前的间隙） <a class="header-anchor" href="#所以数据库数据在加锁是-就是将-19-加了行锁-25-的临键锁-包含-25-及-25-之前的间隙-正无穷的临键锁-正无穷及之前的间隙" aria-label="Permalink to &quot;所以数据库数据在加锁是，就是将 19 加了行锁，25 的临键锁（包含 25 及 25 &lt;span style=&quot;color:red;&quot;&gt;之前&lt;/span&gt;的间隙），正无穷的临键锁（正无穷及之前的间隙）&quot;">​</a></h4></blockquote>',127)])])}const M=t(D,[["render",P]]);export{C as __pageData,M as default};
